  if(!preview.value||preview.value.status==='confirmed'||!selected.value.length||blocking.value.length||busy.value||financialBlocked.value||generatedBlocked.value)return;if(directPosting.value&&!validReview())return;
  if(preview.value.transactions?.length&&!bankAccount.value.trim()){error.value='Identifique a conta bancária para importar o extrato.';return;}
  const batch=preview.value,ctx={...previewContext.value},seq=sequence,revision=postingSequence,bank=bankAccount.value,chosen=[...selected.value];
  if(directPosting.value&&!postingPreview.value){error.value='Valide a revisão depois de conferir as datas e os CFOPs.';return;}
  const posting=directPosting.value?{...payablePayload(),purchase_destination:purchaseDestination.value,...totalReviewPayload(),posting_mode:'book',posting_hash:postingPreview.value.posting_hash,document_overrides:reviewPayload(),cfop_mappings:Object.fromEntries(Object.entries(cfopOverrides.value).filter(([,v])=>v))}:{posting_mode:'pending',create_payables:false,generated_payables:{enabled:false}};
  if(operationalSettings.value.require_extra_confirmations&&!await ask({title:'Confirmar importação?',message:`Os registros serão vinculados a ${ctx.name}, no exercício ${ctx.period.slice(0,4)}, somente nos registros selecionados. ${isFinancial.value?'Os movimentos selecionados ficarão disponíveis para conciliação bancária.':directPosting.value?'Os documentos selecionados já ficarão escriturados no Fiscal, sem criar partidas contábeis. Poderão ser editados conforme os bloqueios e vínculos.':'Documentos fiscais ficarão pendentes de conferência.'} ${payableConsent()}`,confirmLabel:'Importar registros'}))return;
  if(seq!==sequence||revision!==postingSequence||JSON.stringify(chosen)!==JSON.stringify(selected.value)||ctx.id!==state.companyId||(ctx.period.slice(0,4)!==state.period.slice(0,4)||ctx.module!==state.module)){error.value='A prévia ou o contexto mudou. Valide novamente antes de confirmar.';return;}
  busy.value=true;error.value='';
  try{
    const response=await api(scope(`/imports/${batch.id}/confirm`,ctx.id),{method:'POST',body:{preview_hash:batch.preview_hash,bank_account:bank,selected:chosen,...posting}});
    if(seq!==sequence)return;
    result.value=response;batch.status='confirmed';changed();notify(directPosting.value?`${response.documents_booked} documento(s) escriturado(s). A origem permanece preservada.`:'Importação confirmada. Registros disponíveis para conferência.');
  }catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}
}
async function inspect(h){
  if(busy.value||!await mayLeavePreview()||busy.value||confirming.value)return;
  const seq=++sequence,ctx={id:state.companyId,period:state.period,module:state.module,name:company.value?.trade_name||company.value?.name};error.value='';busy.value=true;reprocessing.value=false;billingOnly.value=false;reprocessDirty.value=false;reprocessSelection.value=null;reprocessDocuments.value=[];reprocessResult.value=null;reprocessReason.value='';
  try{
    const inspected=await api(scope(`/imports/${h.id}`,ctx.id));
    if(seq!==sequence||ctx.id!==state.companyId||(ctx.period.slice(0,4)!==state.period.slice(0,4)||ctx.module!==state.module))return;
    postingSequence++;postingPreview.value=null;cfopOverrides.value={};documentOverrides.value={};wholeDocumentCfop.value={};purchaseDestination.value='';batchTotalReview.value=null;createPayables.value=false;generatedPayables.value=emptyGeneratedPlan();supplierTaxIds.value='';visualPreview.value=null;preview.value=inspected;selected.value=[...(inspected.documents||[]),...(inspected.transactions||[])].filter(r=>r._eligibility?.status==='eligible').map(r=>r._selection);previewContext.value={...ctx,period:inspected.period};bankAccount.value=inspected.bank_account||inspected.bank_account_hint||'';result.value=inspected.confirmation||null;file.value=null;busy.value=false;if(inspected.status!=='confirmed'&&directPosting.value)await preparePosting();if(seq===sequence){rememberReview();showHistory.value=false;await focusPanel(previewPanel);}
  }catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}
}
function normalizeReprocess(response){return {...response,documents:(response.documents||[]).map(entry=>{const original=preview.value.documents?.[entry.index]||{};const doc=entry.document||{...original,...entry.after};return {...original,...doc,_selection:entry._selection||`documents:${entry.index}`,_eligibility:{status:entry.eligible?'eligible':'blocked',period:doc.posting_date?.slice(0,7)},posting_lines:entry.posting_lines||doc.posting_lines,import_posting:{...doc.import_posting,eligible:entry.eligible,reason:entry.reason},_reprocess:entry};})};}
async function startReprocessing(preserve=false){
 if(busy.value||startingReprocess.value||preview.value?.status!=='confirmed')return;
 startingReprocess.value=true;const seq=sequence,cid=state.companyId;
 try{billingOnly.value=preserve===true;postingMode.value='book';documentOverrides.value={};cfopOverrides.value={};wholeDocumentCfop.value={};purchaseDestination.value='';batchTotalReview.value=null;generatedPayables.value=emptyGeneratedPlan();supplierTaxIds.value='';reprocessing.value=true;reprocessDocuments.value=[];reprocessSelection.value=null;reprocessDirty.value=false;reprocessResult.value=null;reprocessReason.value=billingOnly.value?'Gerar cobranças XML preservando a escrituração':'';reprocessKey=uid();result.value=null;postingPreview.value=null;selected.value=[];
 await nextTick();if(seq!==sequence||cid!==state.companyId)return;createPayables.value=billingOnly.value;await preparePosting();if(seq===sequence&&cid===state.companyId)rememberReview();
 }finally{startingReprocess.value=false;}
}
async function stopReprocessing(){if(busy.value||!await mayLeavePreview())return;createPayables.value=false;generatedPayables.value=emptyGeneratedPlan();supplierTaxIds.value='';reprocessing.value=false;billingOnly.value=false;reprocessDirty.value=false;reprocessSelection.value=null;reprocessDocuments.value=[];postingPreview.value=null;documentOverrides.value={};cfopOverrides.value={};selected.value=[];}
function selectReprocess(){if(!reprocessing.value)return;reprocessSelection.value=[...selected.value];postingSequence++;reprocessDirty.value=true;}
function diffText(value){if(value===null||value===undefined)return 'Não definido';if(typeof value==='object')return JSON.stringify(value);return String(value);}
async function confirmReprocess(){
 if(busy.value||!postingPreview.value||reprocessDirty.value||financialBlocked.value||generatedBlocked.value||!selected.value.length||!validReview())return;
 if(!reprocessReason.value.trim()){error.value='Informe o motivo do reprocessamento.';return;}
 const ctx={...previewContext.value},batch=preview.value,seq=sequence,revision=postingSequence;
 const body={...(billingOnly.value?{preserve_fiscal:true,create_payables:true}:{...payablePayload(),document_overrides:reviewPayload(),cfop_mappings:Object.fromEntries(Object.entries(cfopOverrides.value).filter(([,v])=>v)),purchase_destination:purchaseDestination.value,...totalReviewPayload()}),selected:[...selected.value],reprocess_hash:postingPreview.value.reprocess_hash,idempotency_key:reprocessKey,reason:reprocessReason.value.trim()};
 if(operationalSettings.value.require_extra_confirmations&&!await ask({title:billingOnly.value?'Gerar cobranças XML?':'Atualizar documentos já importados?',message:billingOnly.value?`Gerar as duplicatas XML selecionadas de ${ctx.name}. CFOPs, datas, valores vNF e decisões fiscais permanecem inalterados. Títulos existentes serão preservados sem duplicação. Não registra baixa nem pagamento.`:`Reprocessar ${body.selected.length} documento(s) de ${ctx.name}. Os IDs e os vínculos existentes serão preservados. Nenhuma nova importação, exclusão de movimentos ou recriação de documentos será realizada. Confira o antes e depois. ${payableConsent()}`,confirmLabel:billingOnly.value?'Gerar cobranças XML':'Atualizar documentos existentes'}))return;
 if(seq!==sequence||revision!==postingSequence||JSON.stringify(body.selected)!==JSON.stringify(selected.value)||ctx.id!==state.companyId||!reprocessing.value){error.value='A revisão mudou. Valide novamente antes de reprocessar.';return;}
 busy.value=true;error.value='';try{const response=await api(scope(`/imports/${batch.id}/reprocess-confirm`,ctx.id),{method:'POST',body});if(seq!==sequence)return;reprocessResult.value=response;reprocessing.value=false;billingOnly.value=false;reprocessDirty.value=false;reprocessSelection.value=null;reprocessDocuments.value=[];postingPreview.value=null;selected.value=[];changed();await reload();notify(response.fiscal_preserved?`${response.titles_created||0} título(s) criado(s), ${response.titles_duplicate||0} já existente(s). Escrituração preservada.`:'Reprocessamento concluído. Documentos existentes preservados.');}catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}
}
function auxiliaryLabel(d){return ({'55':'DANFE','65':'DANFC-e','57':'DACTE'})[d.model]||'';}
function canPreviewAuxiliary(d){return preview.value?.original_available!==false&&auxiliaryLabel(d)&&/\.xml$/i.test(d.source?.file||'')&&can('fiscal.imports','export');}
async function openAuxiliary(d){const index=String(d._selection).split(':')[1];visualPreview.value={title:`${auxiliaryLabel(d)} · documento ${d.number}`,url:`/api${scope(`/imports/${preview.value.id}/documents/${index}/danfe`,previewContext.value.id)}`};await nextTick();visualPanel.value?.scrollIntoView?.({behavior:'smooth',block:'start'});visualPanel.value?.focus?.({preventScroll:true});}
function totalCents(d){if(d.total_cents!==undefined)return d.total_cents;return cents(d.total||'0.00')||0;}
</script>
<template>
<div class="view import-view">
  <header class="view-heading">
    <div><div class="eyebrow">ENTRADA DE DADOS</div><h1>{{isFinancial?'Importação de extratos':'Importações fiscais'}}</h1><p>Selecione o arquivo, confira os registros e confirme a importação.</p></div>
    <div class="actions"><button class="button outline" :disabled="busy" :aria-expanded="showHistory" aria-controls="import-history" @click="showHistory=!showHistory"><Icon name="folder" :size="16"/>Histórico de arquivos ({{history.length}})</button><button v-if="preview&&file&&editablePreview" class="button outline" :disabled="busy||leavingPreview" @click="returnToFile">Voltar ao arquivo</button><button v-if="preview" class="button outline" :disabled="busy||leavingPreview" @click="newImport"><Icon name="import" :size="16"/>Nova importação</button></div>
  </header>
  <ol class="import-steps" aria-label="Etapas da importação">
    <li :class="{current:!preview,done:!!preview}" :aria-current="!preview?'step':undefined"><span>1</span>Selecionar arquivo</li>
    <li :class="{current:preview&&editablePreview,done:preview&&!editablePreview}" :aria-current="preview&&editablePreview?'step':undefined"><span>2</span>Conferir registros</li>
    <li :class="{current:preview&&!editablePreview}" :aria-current="preview&&!editablePreview?'step':undefined"><span>3</span>Concluir</li>
  </ol>
  <p v-if="hasUnsavedReview" class="message info">Há alterações locais nesta conferência. Confirme a importação para salvá-las ou use Nova importação para descartá-las antes de trocar empresa, exercício ou módulo.</p>
  <div v-if="error" class="message error import-error" role="alert"><div><strong>Não foi possível concluir esta etapa</strong><p>{{error}}</p><span class="field-help">{{preview?'Confira o diagnóstico e valide novamente após os ajustes.':file?'O arquivo selecionado continua disponível para uma nova tentativa. Você também pode trocar o arquivo.':'Selecione um arquivo compatível para continuar.'}}</span></div></div>
  <div v-if="busy" class="message info import-progress" role="status" aria-live="polite"><Icon name="loading"/><div><strong>{{!preview?processingStage||'Abrindo arquivo…':'Processando a conferência…'}}</strong><small>Aguarde a conclusão. Arquivos com muitos documentos podem levar mais tempo.</small><progress aria-label="Processamento da importação"/></div></div>
  <section v-show="showHistory" id="import-history" class="panel import-history">
    <div class="panel-heading"><div><h2>Histórico de arquivos</h2><p>{{company?.trade_name||company?.name}} · exercício {{state.period.slice(0,4)}}. Clique em um arquivo para consultar ou retomar.</p></div><button class="text-button" @click="showHistory=false">Fechar histórico</button></div>
    <div v-if="history.length" class="history-search"><label>Buscar arquivo no histórico<input v-model="historySearch" type="search" placeholder="Nome do arquivo"/></label></div>
    <div v-if="filteredHistory.length" class="history-list"><button v-for="h in filteredHistory" :key="h.id" :disabled="busy||leavingPreview" @click="inspect(h)"><span class="file-icon"><Icon name="file"/></span><span><strong>{{h.filename}}</strong><small>{{dateTime(h.created_at)}} · {{h.format||'Arquivo'}}</small></span><span class="badge" :class="h.status==='confirmed'?'success':'neutral'">{{h.status==='confirmed'?'Importado':'Retomar prévia'}}</span><Icon name="arrow" :size="15"/></button></div>
    <EmptyState v-else :title="history.length?'Nenhum arquivo encontrado':'Nenhum arquivo processado'" text="Os arquivos analisados ficam disponíveis aqui para consulta." icon="folder"/>
    <ImportPackageControls v-if="!isFinancial&&can('fiscal.imports')" @cleaned="reload"/>
  </section>
  <section v-if="!preview" ref="uploadPanel" tabindex="-1" class="panel upload-panel">
    <div class="panel-heading"><div><h2>Selecionar arquivo</h2><p>{{company?.trade_name||company?.name}} · exercício {{state.period.slice(0,4)}} · competência ativa {{state.period.split('-').reverse().join('/')}}</p></div></div>
    <div class="dropzone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="chooseFiles($event.dataTransfer.files)">
      <span class="upload-circle"><Icon :name="file?'filecheck':'import'" :size="24"/></span>
      <div class="file-choice"><strong>{{file?.name||'Arraste o arquivo ou clique em Selecionar arquivo'}}</strong><small>{{file?`${(file.size/1024).toFixed(1)} KB · pronto para analisar`:isFinancial?'OFX · QFX · QIF · OFC · CSV/TXT · ZIP / 7z / RAR':'XML · SPED/TXT · CSV · ZIP / 7z / RAR'}}</small><small v-if="!file">Um arquivo por vez. Use um pacote compactado para reunir vários documentos.</small></div>
      <input ref="input" type="file" :accept="fileAccept" :disabled="busy" @click="$event.target.value=''" @change="chooseFiles($event.target.files)" aria-label="Selecionar arquivo de importação"/>
      <button class="button outline" type="button" @click="input.click()" :disabled="busy">{{file?'Trocar arquivo':'Selecionar arquivo'}}</button><button v-if="file" class="text-button" type="button" :disabled="busy" @click="resetImport">Remover seleção</button>
    </div>
    <div class="upload-options"><p v-if="operationalSettings.block_imports" class="message warning">Importações bloqueadas nos parâmetros operacionais desta empresa. Um administrador pode desativar essa regra em Empresas → Operação.</p><p v-if="operationalSettings.limit_import_size" class="field-help">Limite configurado nesta empresa: {{operationalSettings.import_size_mb}} MiB.</p><p class="field-help">Limites operacionais são configurados no cadastro da empresa. Limite técnico de segurança: 128 MiB por arquivo.</p><p v-if="!isFinancial" class="field-help">Para recuperar um original removido na limpeza, envie novamente o mesmo arquivo. Os movimentos já importados não serão duplicados.</p>
      <label v-if="!isFinancial" class="posting-option">Data de escrituração do XML (opcional)<DateInput ref="postingInput" v-model="options.posting_date" :disabled="busy"/><small>Deixe em branco para revisar a data de cada documento na prévia.</small></label>
      <label v-else>Conta bancária do extrato<input v-model="bankAccount" :disabled="busy" placeholder="Ex.: Banco / agência / conta"/><small>Identifique a conta antes de confirmar os movimentos.</small></label>
    </div>
    <div class="panel-action upload-action"><span class="field-help">{{file?'O arquivo será analisado. Nada será escriturado sem sua confirmação.':'Selecione um arquivo para continuar.'}}</span><button class="button primary" v-allow="[routine,'import']" @click="analyze" :disabled="!file||busy"><Icon :name="busy?'loading':'search'"/>{{busy?'Processando arquivo...':'Analisar e gerar prévia'}}</button></div>
    <div v-if="readingOptionsAvailable" class="upload-options advanced-reading">
      <button class="text-button" :aria-expanded="showOptions" aria-controls="import-reading-options" @click="showOptions=!showOptions"><Icon name="settings" :size="16"/>Opções avançadas de leitura<Icon name="down" :size="15"/></button>
      <div v-if="showOptions" id="import-reading-options" class="form-grid three">
        <label>Formato da data<select v-model="options.date_format" :disabled="busy"><option value="">Padrão do formato</option><option value="DMY">Dia / mês / ano</option><option value="YMD">Ano / mês / dia</option><option value="MDY">Mês / dia / ano</option></select></label>
        <label>Codificação<select v-model="options.encoding" :disabled="busy"><option value="auto">Detectar com conferência</option><option value="utf-8">UTF-8</option><option value="cp1252">Windows-1252</option></select></label>
        <label>Separador<select v-model="options.delimiter" :disabled="busy"><option value=";">Ponto e vírgula</option><option value=",">Vírgula</option><option :value="'\t'">Tabulação</option></select></label>
        <label>Separador decimal<select v-model="options.decimal_separator" :disabled="busy"><option value="">Padrão do formato</option><option value=",">Vírgula (1.234,56)</option><option value=".">Ponto (1,234.56)</option></select></label>
        <label>Separador de milhares<select v-model="options.thousands_separator" :disabled="busy"><option value="auto">Padrão do formato</option><option value=".">Ponto</option><option value=",">Vírgula</option><option value="">Sem separador</option></select></label>
        <p v-if="isFinancial" class="field-help span-3">CSV bancário: cabeçalhos data, valor, historico e documento. Valores negativos são saídas; positivos, entradas. Separe extratos com convenções numéricas diferentes.</p><p v-else class="field-help span-3">Ajuste apenas se o arquivo exigir uma convenção de leitura diferente. XML mantém o formato declarado na origem.</p>
      </div>
    </div>
  </section>
<div v-if="preview?.original_restored" class="message success" role="status"><Icon name="checks"/><span>Original recuperado com sucesso. O lote e os movimentos existentes foram preservados, sem duplicação.</span></div>
<div v-if="preview?.original_available===false" class="message info"><span>Para recuperar o original, clique em Nova importação e selecione exatamente o mesmo arquivo. Os movimentos existentes serão preservados.</span></div>
<section v-if="preview" ref="previewPanel" tabindex="-1" class="panel preview-panel"><div class="panel-heading"><div><h2>Prévia · {{preview.filename}}</h2><p>{{previewContext?.name}} · {{preview.period.split('-').reverse().join('/')}} · {{preview.format}}</p></div><button v-if="state.module==='fiscal'&&preview.status==='confirmed'&&!reprocessing&&can('fiscal.documents','edit')" class="button outline" :disabled="busy||startingReprocess" @click="startReprocessing(false)">Revisar / reprocessar existentes</button><button v-if="state.module==='fiscal'&&preview.status==='confirmed'&&!reprocessing&&can('fiscal.documents','edit')&&canCreatePayables" class="button primary" :disabled="busy||startingReprocess" @click="startReprocessing(true)">Gerar cobranças XML</button><a v-if="preview.original_available!==false" v-allow="[routine,'export']" class="button outline small" :href="`/api${scope(`/imports/${preview.id}/original`,previewContext.id)}`" download>Baixar original</a><span v-if="preview.original_available===false" class="badge warning">Original indisponível após limpeza</span><span class="badge" :class="blocking.length?'warning':preview.status==='confirmed'?'success':'info'">{{blocking.length?'Requer correção':preview.status==='confirmed'?'Importação confirmada':'Aguardando confirmação'}}</span></div><div class="summary-strip"><div><strong>{{selected.length}}</strong><span>selecionados para esta operação</span></div><div v-if="!isFinancial||preview.documents?.length"><strong>{{preview.documents?.length||0}}</strong><span>documentos</span></div><div v-if="isFinancial||preview.transactions?.length"><strong>{{preview.transactions?.length||0}}</strong><span>movimentos bancários</span></div><div><strong>{{blocking.length}}</strong><span>impedimentos</span></div><div><strong>{{(preview.issues?.length||0)-blocking.length}}</strong><span>avisos e informações</span></div><span class="push-right mono subtle">Origem SHA-256 {{preview.sha256?.slice(0,12)}}…</span></div><details v-if="preview.issues?.length" :open="blocking.length>0"><summary class="panel-body">{{blocking.length}} impedimentos · {{preview.issues.length-blocking.length}} avisos e informações (não impedem a importação). Ver detalhes</summary><div class="issues-list"><div v-for="(issue,i) in preview.issues" :key="i" class="message" :class="issueKind(issue)"><Icon name="alert" :size="17"/><div><strong>{{issueLabel(issue)}}</strong><span>{{issue.message}}</span><small>{{issue.code}}</small></div></div></div></details>
<section v-if="state.module==='fiscal'&&preview.documents?.length&&editablePreview&&!billingOnly" class="panel-body import-review-settings"><p v-if="reprocessing" class="message warning">Revisão de lote confirmado: serão atualizados somente documentos existentes selecionados, preservando IDs e vínculos. Nenhum movimento será excluído.</p><h3>Confira os documentos abaixo</h3><p>Revise a data de escrituração e o CFOP. Se alterar algum campo, valide a revisão antes de confirmar.</p><div class="form-grid"><label v-if="!reprocessing">Ao confirmar esta importação<select v-model="postingMode" :disabled="busy" aria-label="Modo de escrituração da importação"><option v-if="can('fiscal.documents','book')" value="book">Importar e escriturar no Fiscal</option><option value="pending">Importar para conferência individual</option></select></label><div v-if="directPosting" class="actions"><button class="button outline" :disabled="busy" @click="preparePosting">Validar revisão e selecionar aptos</button><button v-if="can('fiscal.masters')" class="text-button" @click="navigate('cfop')">CFOP e associações da empresa</button></div></div><template v-if="directPosting"><details class="import-optional" :open="createPayables||generatedPayables.enabled"><summary>Contas a pagar (opcional)<span>{{createPayables||generatedPayables.enabled?'Geração selecionada':'Não gerar títulos'}}</span></summary><section class="panel panel-body"><label class="inline-choice"><input v-model="generatedPayables.enabled" type="checkbox" :disabled="busy||(!generatedPayables.enabled&&!canCreatePayables)"/>Gerar uma parcela por compra sem cobrança no XML</label><p class="field-help">Opcional. Não substitui cobrança existente, não consolida notas, não realiza pagamento nem baixa. As parcelas são geradas pela regra do usuário, não declaradas no XML.</p><template v-if="generatedPayables.enabled"><div class="form-grid"><label>Selecionar compras por<select v-model="generatedSelectionMode" :disabled="busy"><option value="notes">Notas individuais</option><option value="suppliers">CNPJs dos fornecedores</option></select></label><label v-if="generatedSelectionMode==='suppliers'">CNPJs dos fornecedores<textarea v-model="supplierTaxIds" :disabled="busy" placeholder="Separe CNPJs por espaço, vírgula ou ponto e vírgula"/></label><label>Prazo em dias<input v-model.number="generatedPayables.term_days" type="number" min="0" step="1" required :disabled="busy"/></label><label>Base do vencimento<select v-model="generatedPayables.date_basis" required :disabled="busy"><option value="">Escolha a base</option><option value="issue">Data de emissão</option><option value="receipt">Entrada efetiva da mercadoria</option></select></label><label>Responsável<input v-model="generatedPayables.responsible" required :disabled="busy"/></label><label>Motivo / referência<input v-model="generatedPayables.reason" required :disabled="busy"/></label></div><p>Valide a revisão para conferir uma parcela por nota antes de confirmar. A falta da entrada efetiva bloqueia o plano baseado nessa data. Desative esta opção para importar somente o Fiscal.</p></template></section><section class="panel panel-body"><label class="inline-choice"><input v-model="createPayables" type="checkbox" :disabled="busy||(!createPayables&&(!canCreatePayables||!payableCandidates))"/>Gerar contas a pagar das parcelas do XML</label><p class="field-help">Opção facultativa para entradas NF-e/NFC-e com parcelas explícitas no XML. Cria títulos em aberto, sem baixa, pagamento ou movimentação bancária. Vencimento não é data de pagamento. A reimportação preserva os títulos já vinculados.</p><p v-if="!canCreatePayables" class="field-help">É necessária permissão para criar títulos financeiros.</p><p v-else-if="!payableCandidates" class="field-help">Sem parcelas de cobrança no XML: nenhuma conta a pagar será criada.</p><p v-if="createPayables" class="message info">{{selectedInstallments}} parcela(s) nos documentos selecionados. Valide a revisão após alterar esta opção. Se houver impedimento financeiro, desmarque a opção e valide novamente para importar somente o Fiscal.</p><p v-else class="field-help">Somente Fiscal selecionado. A ausência ou inconsistência de cobrança não impede a importação fiscal.</p></section></details><details class="import-optional" :open="!!batchTotalReview||mappingRequirements.length>0"><summary>Ajustes fiscais do lote (opcional)<span>Destinação, associações de CFOP e totalizadores</span></summary><section class="panel panel-body"><label class="inline-choice"><input type="checkbox" :checked="!!batchTotalReview" :disabled="busy" @change="chooseBatchTotalReview($event.target.checked)"/>Conferi totalizadores do lote: usar vNF da origem conforme referência</label><p class="field-help">Decisão explícita para os documentos do lote com totalizadores divergentes. Não representa validação legal da RTC. Revise vNF, vNFTot e a diferença por documento abaixo.</p><div v-if="batchTotalReview" class="form-grid"><label>Fonte / referência<input v-model="batchTotalReview.source" :disabled="busy" required/></label><label>Responsável<input v-model="batchTotalReview.responsible" :disabled="busy" required/></label><label>Motivo<input v-model="batchTotalReview.reason" :disabled="busy" required/></label></div></section><label>Destinação das compras neste lote<select v-model="purchaseDestination" :disabled="busy"><option value="">Usar padrão da empresa / conferir</option><option v-for="[value,label] in destinations" :key="value" :value="value">{{label}}</option></select><small>Apenas classifica a operação. Não define créditos ou tratamento tributário.</small></label><div v-if="mappingRequirements.length" class="form-grid three"><label v-for="r in mappingRequirements" :key="r.key">{{r.direction==='incoming'?'Entrada':'Saída'}} · modelo {{r.model}} · origem {{r.source}}<CfopInput v-model="cfopOverrides[r.key]" :disabled="busy" :direction="r.direction" :date="r.date" placeholder="Usar associação da empresa" :aria-label="`CFOP de escrituração para ${r.key}`"/></label></div><p>As escolhas deste lote não alteram as associações salvas da empresa. O CFOP e os valores originais são preservados; não há cálculo de tributos, criação de títulos ou contabilização implícita.</p></details><p v-if="!postingPreview||reprocessDirty" class="message info">Edite a data e o CFOP na tabela abaixo. Depois, clique em “Validar revisão e selecionar aptos”. Alterações exigem nova validação antes de confirmar.</p></template><p v-else class="message info">Neste modo, os documentos ficam pendentes. A data inicial vem das opções de leitura; a classificação e as datas serão editadas em Escrituração e documentos antes de escriturar.</p></section><section v-if="billingOnly" class="panel-body billing-only-review"><h3>Gerar cobranças XML sem alterar a escrituração</h3><p class="message info">Somente duplicatas explícitas de notas de compra já escrituradas. CFOPs, datas, valores vNF, revisões e vínculos fiscais ficam intactos. Não gera parcelas por regra, pagamentos ou baixas.</p><p v-if="postingPreview?.billing_summary" class="message subtle"><strong>{{postingPreview.billing_summary.documents}} notas · {{postingPreview.billing_summary.installments}} parcelas · {{money(postingPreview.billing_summary.amount_cents)}}</strong><span v-if="reprocessDirty"> · seleção alterada, atualize a prévia</span></p><button v-if="reprocessDirty||!postingPreview" type="button" class="button outline" :disabled="busy||!selected.length" @click="preparePosting">Atualizar prévia das cobranças</button><div class="table-scroll"><table><thead><tr><th>Selecionar</th><th>Nota</th><th>CFOP mantido</th><th>Escrituração mantida</th><th>Valor documental mantido</th><th>Duplicatas XML</th><th>Diagnóstico</th></tr></thead><tbody><tr v-for="d in documentRows" :key="d._selection"><td><input v-model="selected" type="checkbox" :value="d._selection" :disabled="busy||!d._reprocess?.eligible" @change="selectReprocess" :aria-label="`Gerar cobrança da nota ${d.number}`"/></td><td>{{d.number}} · {{d.partner_name}}</td><td>{{d.cfop||'Por item'}}</td><td>{{date(d.posting_date)}}</td><td>{{money(totalCents(d))}}</td><td><div v-for="p in d.financial_posting?.installments||[]" :key="p.number">{{p.number}} · {{date(p.due_date)}} · {{money(p.amount_cents)}}</div></td><td>{{d._reprocess?.reason||(d.financial_posting?.status==='existing'?'Já geradas; preservar sem duplicar':'Pronta para gerar')}}</td></tr></tbody></table></div></section><form v-if="!billingOnly" ref="reviewForm" @submit.prevent="preparePosting"><div v-if="preview.documents?.length" class="table-scroll preview-table"><table><thead><tr><th>Selecionar</th><th>Competência / diagnóstico</th><th>Documento</th><th>Participante</th><th>Emissão (origem)</th><th>Entrada/saída (origem)</th><th>Escrituração / competência</th><th>CFOP de escrituração</th><th>Operação</th><th class="right">Total</th></tr></thead><tbody><template v-for="(d,i) in documentRows" :key="d._selection||i"><tr><td><input type="checkbox" v-model="selected" :value="d._selection" @change="selectReprocess" :disabled="d._eligibility?.status!=='eligible'||!editablePreview||(directPosting&&(!postingPreview||!d.import_posting?.eligible))" :aria-label="`Selecionar documento ${d.number}`"/></td><td>{{d._eligibility?.period}} · {{directPosting?(d.import_posting?.reason||'Valide a revisão'):d._eligibility?.reason}}<small v-if="directPosting&&d.import_posting?.eligible" class="cell-secondary">CFOP {{d.items?.length?[...new Set(d.items.map(i=>i.cfop))].join(', '):d.cfop}}</small></td><td class="mono">{{d.number}}<button v-if="canPreviewAuxiliary(d)" type="button" class="text-button" @click="openAuxiliary(d)">Visualizar {{auxiliaryLabel(d)}}</button></td><td>{{d.partner_name}}</td><td>{{date(d.issue_date)}}</td><td>{{d.movement_date?date(d.movement_date):'Não informada'}}<small class="cell-secondary">Data da origem XML; não presume recebimento.</small><label v-if="d.direction==='incoming'">Entrada efetiva da mercadoria<DateInput v-if="directPosting&&editablePreview" :model-value="reviewValue(d,'receipt_date')" @update:model-value="reviseDocument(d,'receipt_date',$event)" :disabled="busy" :aria-label="`Entrada efetiva do documento ${d.number}`"/><span v-else>{{d.receipt_date?date(d.receipt_date):'Não informada'}}</span></label><button v-if="directPosting&&editablePreview&&reviewValue(d,'receipt_date')" type="button" class="text-button" :disabled="busy" @click="useReceiptForPosting(d)">Usar entrada como data de escrituração</button></td><td><DateInput v-if="directPosting&&editablePreview" :model-value="reviewValue(d,'posting_date')" @update:model-value="reviseDocument(d,'posting_date',$event)" :disabled="busy" required :aria-label="`Data de escrituração do documento ${d.number}`"/><span v-else>{{date(d.posting_date)}}</span><label v-if="directPosting&&editablePreview&&d.direction==='incoming'&&d.posting_date_proposed" class="inline-choice"><input type="checkbox" :checked="!!reviewValue(d,'posting_date_confirmed')" :disabled="busy" @change="reviseDocument(d,'posting_date_confirmed',$event.target.checked)"/>Confirmei a entrada/competência</label></td><td><template v-if="directPosting&&editablePreview"><CfopInput :model-value="reviewValue(d,'cfop')" @update:model-value="reviseDocument(d,'cfop',$event)" :disabled="busy||!allowWholeDocumentCfop(d)" :direction="d.direction" :date="reviewValue(d,'posting_date')" pattern="[0-9]{4}" placeholder="Manter / usar associação" :aria-label="`CFOP do documento ${d.number}`"/><label v-if="d.direction==='incoming'">Destinação do documento<select :value="reviewValue(d,'purchase_destination')" :disabled="busy" @change="reviseDocument(d,'purchase_destination',$event.target.value)"><option value="">Usar lote / empresa</option><option v-for="[value,label] in destinations" :key="value" :value="value">{{label}}</option></select></label><small class="cell-secondary">Se preenchido, substitui o CFOP de todos os itens.</small><label v-if="documentCfops(d).length>1" class="inline-choice"><input type="checkbox" :checked="wholeDocumentCfop[d._selection]" :disabled="busy" @change="toggleWholeDocumentCfop(d,$event.target.checked)"/>Aplicar um único CFOP a todos os itens</label><small v-if="documentCfops(d).length>1" class="cell-secondary warning">Atenção: a origem contém múltiplos CFOPs. Preserve o desdobramento ou autorize expressamente a substituição.</small></template><span class="cell-secondary">{{d.items?.length?[...new Set(d.items.map(i=>i.cfop).filter(Boolean))].join(', '):d.cfop||'A definir'}}</span></td><td>{{d.direction==='incoming'?'Entrada':d.direction==='outgoing'?'Saída':'A conferir'}}</td><td class="right money">{{money(totalCents(d))}}<small class="cell-secondary">Total único da nota</small></td></tr>
<tr v-if="reprocessing&&d._reprocess" class="analytic-detail"><td colspan="10"><strong>Documento existente #{{d._reprocess.id}} · versão {{d._reprocess.version}} · {{d._reprocess.reason}}</strong><details open><summary>Antes e depois do reprocessamento</summary><div class="table-scroll"><table><thead><tr><th>Campo</th><th>Antes</th><th>Depois</th></tr></thead><tbody><tr v-for="(change,key) in d._reprocess.diffs" :key="key"><td>{{change.field||key}}</td><td class="diff-value">{{diffText(change.old)}}</td><td class="diff-value">{{diffText(change.new)}}</td></tr></tbody></table></div></details></td></tr><tr class="analytic-detail"><td colspan="10"><details class="document-import-details"><summary>Detalhes do documento {{d.number}} · itens, tributos e cobrança</summary><section v-if="['55','65'].includes(String(d.model))" class="panel panel-body" aria-label="Cobrança declarada no XML"><h4>Cobrança declarada no XML</h4><label v-if="generatedPayables.enabled&&generatedSelectionMode==='notes'&&generatedCandidate(d)&&editablePreview" class="inline-choice"><input v-model="generatedPayables.selected" :value="d._selection" type="checkbox" :disabled="busy"/>Gerar uma parcela para esta compra sem cobrança</label><p v-if="!d.billing?.present">Cobrança não informada no XML. Nenhuma parcela presumida.</p><template v-else><p>Fatura: {{d.billing.invoice?.number||'Não informado'}} · Valor bruto: {{billingMoney(d.billing.invoice?.original_amount)}} · Desconto: {{billingMoney(d.billing.invoice?.discount)}} · Valor líquido: {{billingMoney(d.billing.invoice?.net_amount)}}</p><div v-if="d.billing.installments?.length" class="table-scroll"><table aria-label="Parcelas de cobrança do XML"><thead><tr><th>Parcela / número na origem</th><th>Vencimento (não é pagamento)</th><th class="right">Valor da parcela</th></tr></thead><tbody><tr v-for="(installment,index) in d.billing.installments" :key="installment.sequence??index"><td>{{installment.number||'Não informado'}}<small class="cell-secondary">Sequência na origem: {{installment.sequence??index+1}}</small></td><td>{{installment.due_date?date(installment.due_date):'Não informado'}}</td><td class="right money">{{billingMoney(installment.amount)}}</td></tr></tbody></table></div><p v-else>Parcelas não informadas no XML. Nenhuma conta a pagar presumida.</p></template><ul v-if="d.billing?.issues?.length" class="message warning"><li v-for="(issue,index) in d.billing.issues" :key="index">{{billingIssue(issue)}}</li></ul><p v-if="d.billing?.financial_rules_pending" class="field-help">Dados de cobrança sujeitos à revisão financeira. Não representam pagamento realizado.</p><p v-if="d.financial_posting" :class="['message',createPayables&&d.financial_posting.eligible===false&&d.financial_posting.status!=='not_applicable'?'warning':'info']">{{d.financial_posting.reason||'Confira a geração de contas a pagar.'}}</p><section v-if="generatedPayables.enabled&&d.generated_financial_posting&&d.generated_financial_posting.status!=='not_applicable'" class="panel panel-body"><h4>Parcela proposta pela regra do usuário (não consta no XML)</h4><p>{{d.generated_financial_posting.reason}}</p><p v-for="(installment,index) in d.generated_financial_posting.installments||[]" :key="index">Parcela única · Vencimento: {{installment.due_date?date(installment.due_date):'Pendente'}} · Valor: {{billingMoney(installment.amount)}}</p><p v-if="d.generated_financial_posting.title_ids?.length">Títulos vinculados: {{d.generated_financial_posting.title_ids.join(', ')}}</p></section><div v-if="generatedPayables.enabled&&generatedCandidate(d)&&editablePreview" class="form-grid"><label>Ajustar valor da parcela (opcional)<input :value="generatedPayables.overrides[d._selection]?.amount||''" inputmode="decimal" placeholder="Ex.: 100.00" :disabled="busy" @input="generatedOverride(d,'amount',$event.target.value)"/></label><label>Ajustar vencimento (opcional)<DateInput :model-value="generatedPayables.overrides[d._selection]?.due_date||''" :disabled="busy" @update:model-value="generatedOverride(d,'due_date',$event)"/></label><label>Motivo do ajuste<input :value="generatedPayables.overrides[d._selection]?.reason||''" :disabled="busy" @input="generatedOverride(d,'reason',$event.target.value)"/></label></div><p v-if="d.financial_posting?.title_ids?.length">Títulos vinculados preservados: {{d.financial_posting.title_ids.join(', ')}}</p></section><section v-if="totalComparison(d)" class="panel panel-body"><h4>Conferência de totalizadores da origem</h4><p>vNF: {{lineMoney(totalComparison(d).vNF)}} · vNFTot: {{lineMoney(totalComparison(d).declared_new_total)}} · Diferença: {{lineMoney(totalComparison(d).difference)}}</p><template v-if="directPosting&&editablePreview"><label class="inline-choice"><input type="checkbox" :checked="!!totalReview(d)" :disabled="busy" @change="chooseTotalReview(d,$event.target.checked)"/>Conferi totalizadores: usar vNF da origem conforme referência</label><p class="field-help">A decisão deste documento prevalece sobre a do lote. Sem decisão aplicável, a divergência continua bloqueada. Esta revisão não valida legalmente a RTC.</p><div v-if="totalReview(d)" class="form-grid"><label>Fonte / referência<input :value="totalReview(d).source" :disabled="busy" required @input="reviseTotalReview(d,'source',$event.target.value)"/></label><label>Responsável<input :value="totalReview(d).responsible" :disabled="busy" required @input="reviseTotalReview(d,'responsible',$event.target.value)"/></label><label>Motivo<input :value="totalReview(d).reason" :disabled="busy" required @input="reviseTotalReview(d,'reason',$event.target.value)"/></label></div><p v-else-if="batchTotalReview" class="field-help">Decisão do lote selecionada. O resultado depende da validação da revisão.</p></template></section><details><summary>Desdobramento da escrituração · {{d.posting_lines?.length||0}} linha(s) · CFOP de origem: {{documentCfops(d).join(', ')||'Não informado'}}</summary><p class="field-help">Uma única nota, agrupada por CFOP, CST/CSOSN, alíquota e tratamento. Os valores das linhas são parcelas do documento, não novas notas. Valores fiscais pendentes não significam zero.</p><div v-if="directPosting&&editablePreview" class="form-grid"><label>Tratamento fiscal deste documento<select :value="treatmentValue(d).book_mode||''" :disabled="busy" @change="chooseTreatment(d,$event.target.value)"><option value="">Sem decisão fiscal</option><option value="other_excluding_ipi">Outras = valor contábil − IPI, sem crédito automático</option></select></label><template v-if="treatmentValue(d).book_mode"><label>Fundamento / referência revisada<input :value="treatmentValue(d).source" :disabled="busy" required @input="reviseTreatment(d,'source',$event.target.value)"/></label><label>Responsável pela revisão<input :value="treatmentValue(d).responsible" :disabled="busy" required @input="reviseTreatment(d,'responsible',$event.target.value)"/></label><label>Vigência inicial<DateInput :model-value="treatmentValue(d).valid_from" :disabled="busy" required @update:model-value="reviseTreatment(d,'valid_from',$event)"/></label><label>Vigência final<DateInput :model-value="treatmentValue(d).valid_to" :disabled="busy" @update:model-value="reviseTreatment(d,'valid_to',$event)"/></label><p class="field-help">Decisão explícita para este documento. O regime do emitente não autoriza o tratamento; tributos declarados no XML permanecem preservados.</p></template></div><details v-if="directPosting&&editablePreview&&d.direction==='incoming'&&d.items?.length"><summary>Revisar destinação por item</summary><div class="form-grid three"><label v-for="item in d.items" :key="item.number">Item {{item.number}} · {{item.description||item.product_code||item.source_cfop}}<select :value="documentOverrides[d._selection]?.item_destinations?.[String(item.number)]||''" :disabled="busy" @change="reviseItemDestination(d,item,$event.target.value)"><option value="">Usar documento / lote / empresa</option><option v-for="[value,label] in destinations" :key="value" :value="value">{{label}}</option></select></label></div></details><section v-if="directPosting&&editablePreview&&d.items?.length" class="panel panel-body"><h4>Agrupamento revisado por item (opcional)</h4><p class="field-help">Sem revisão, o desdobramento segue CFOP, CST/CSOSN, alíquota e tratamento da origem. A revisão não modifica o XML. Não deduza grupos por coincidência de valores.</p><button v-if="!groupReview(d)" type="button" class="button outline" :disabled="busy" @click="startGroupReview(d)">Iniciar revisão de grupos</button><template v-else><div class="form-grid"><label>Modo da revisão<select :value="groupReview(d).mode" :disabled="busy" @change="reviseGroupReview(d,'mode',$event.target.value)"><option value="split">Separar por grupo, preservando critérios fiscais</option><option value="consolidate" :disabled="treatmentValue(d).book_mode!=='other_excluding_ipi'">Consolidar grupo com tratamento revisado de Outras</option></select></label><label>Fonte / referência<input :value="groupReview(d).source" :disabled="busy" required @input="reviseGroupReview(d,'source',$event.target.value)"/></label><label>Responsável<input :value="groupReview(d).responsible" :disabled="busy" required @input="reviseGroupReview(d,'responsible',$event.target.value)"/></label><label>Motivo da revisão<input :value="groupReview(d).reason" :disabled="busy" required @input="reviseGroupReview(d,'reason',$event.target.value)"/></label><label v-for="item in d.items" :key="item.number">Grupo do item {{item.number}} · {{item.description||item.product_code||item.source_cfop}}<input :value="groupReview(d).item_groups[String(item.number)]" :disabled="busy" required maxlength="100" placeholder="Defina o grupo deste item" @input="reviseItemGroup(d,item,$event.target.value)"/></label></div><p v-if="groupReview(d).mode==='consolidate'" class="message warning">Consolidação exige tratamento de Outras válido e o mesmo CFOP/tratamento. Classificações tributárias diferentes continuam preservadas nos detalhes da origem.</p><button type="button" class="text-button" :disabled="busy" @click="removeGroupReview(d)">Desativar revisão e voltar ao agrupamento automático</button></template></section><ul v-if="d.import_posting?.mappings?.length" class="classification-audit"><li v-for="(mapping,mappingIndex) in d.import_posting.mappings" :key="mappingIndex">{{mapping.item_number?`Item ${mapping.item_number} · `:''}}Origem {{mapping.source_cfop}} → escrituração {{mapping.target_cfop}} · {{mappingOrigin(mapping.origin)}} · {{destinations.find(option=>option[0]===mapping.purchase_destination)?.[1]||mapping.purchase_destination||'Destinação a conferir'}}<small class="cell-secondary">{{mapping.reason||mapping.mapping_snapshot?.reason}} {{mapping.version?`Versão ${mapping.version}`:''}} · {{mapping.responsible||'Revisão do lote'}}<span v-if="mapping.source_catalog_version"> · Catálogo {{mapping.source_catalog_version}}</span></small></li></ul><div v-if="d.posting_lines?.length" class="table-scroll"><table aria-label="Linhas analíticas de escrituração"><thead><tr><th>Grupo / modo</th><th>CFOP</th><th>CST / CSOSN</th><th>Alíquota</th><th>Tratamento / pendências</th><th>Itens</th><th class="right">Valor da linha</th><th class="right">Base escriturada</th><th class="right">ICMS escriturado</th><th class="right">Outras</th><th class="right">IPI escriturado</th></tr></thead><tbody><tr v-for="(line,lineIndex) in d.posting_lines" :key="lineIndex"><td>{{line.posting_group||'Automático'}}<small class="cell-secondary">{{line.grouping_mode==='consolidate'?'Consolidado por revisão':line.grouping_mode==='split'?'Separado por revisão':'Critérios fiscais'}}</small></td><td>{{line.cfop||'Pendente'}}</td><td>{{line.cst_icms||line.csosn||'Não informado'}}</td><td>{{line.rate===null||line.rate===undefined?'Não informada':line.rate+'%'}}</td><td>{{treatmentLabel(line.treatment)}}<small v-if="line.pending" class="cell-secondary">{{pendingLabel(line.pending)}}</small><details v-if="line.declared_classifications?.length"><summary>Classificações preservadas da origem</summary><ul><li v-for="(classification,index) in line.declared_classifications" :key="index">{{classificationLabel(classification)}}</li></ul></details><details v-if="Object.keys(line.declared_taxes||{}).length"><summary>Tributos declarados na origem</summary><dl><template v-for="(value,key) in line.declared_taxes" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></template></dl><small>Valores de origem; não representam crédito autorizado.</small></details></td><td>{{line.item_numbers?.join(', ')||'Analítico de origem'}}</td><td class="right money">{{lineMoney(line.document_total)}}</td><td class="right money">{{lineMoney(line.book_base)}}</td><td class="right money">{{lineMoney(line.book_icms)}}</td><td class="right money">{{lineMoney(line.book_other)}}</td><td class="right money">{{lineMoney(line.book_ipi)}}</td></tr></tbody></table></div><p v-else class="field-help">Valide a revisão para conferir as linhas analíticas.</p></details></details></td></tr></template></tbody></table></div></form><div v-if="preview.transactions?.length&&editablePreview" class="panel-body"><label>Conta bancária do extrato<input v-model="bankAccount" :disabled="busy" placeholder="Ex.: Banco / agência / conta"/></label></div><div v-if="preview.transactions?.length" class="table-scroll preview-table"><table><thead><tr><th>Selecionar</th><th>Diagnóstico</th><th>Data</th><th>Histórico</th><th>Referência</th><th class="right">Valor</th></tr></thead><tbody><tr v-for="(t,i) in preview.transactions" :key="i"><td><input type="checkbox" v-model="selected" :value="t._selection" :disabled="t._eligibility?.status!=='eligible'||preview.status==='confirmed'" aria-label="Selecionar movimento"/></td><td>{{t._eligibility?.reason}}</td><td>{{date(t.date)}}</td><td>{{t.description}}</td><td class="mono">{{t.reference||t.external_id}}</td><td class="right money" :class="Number(t.amount)<0?'negative':'positive'">{{money(t.amount_cents??Math.round(Number(t.amount)*100))}}</td></tr></tbody></table></div><div v-if="result" class="message success"><Icon name="checks"/><span>{{result.documents_booked||0}} documentos escriturados · {{result.documents_created||0}} documentos e {{result.transactions_created||0}} movimentos incluídos. {{(result.documents_duplicate||0)+(result.transactions_duplicate||0)}} registros já existentes preservados sem duplicação.</span></div><div v-if="result?.source_version_warnings?.length" class="message warning"><div><strong>Versões XML preservadas para comparação</strong><ul><li v-for="warning in result.source_version_warnings" :key="warning">{{warning}}</li></ul></div></div><div v-if="result?.master_import_warnings?.length" class="message warning"><div><strong>Cadastros exigem revisão</strong><ul><li v-for="warning in result.master_import_warnings" :key="warning">{{warning}}</li></ul></div></div><section v-if="reprocessing" class="panel-body"><label>Motivo do reprocessamento<input v-model="reprocessReason" :disabled="busy" required maxlength="1000"/></label><button class="text-button" :disabled="busy" @click="stopReprocessing">Cancelar revisão do lote confirmado</button></section><p v-if="reprocessResult" class="message success">{{reprocessResult.fiscal_preserved?`${reprocessResult.titles_created||0} título(s) criado(s) · ${reprocessResult.titles_duplicate||0} já existente(s). CFOPs, datas, valores e revisões fiscais preservados.`:'Reprocessamento concluído. IDs e vínculos preservados; nenhum movimento excluído.'}}</p><footer class="panel-action split import-confirmation"><div class="confirmation-status"><strong v-if="editablePreview">{{confirmationHint}}</strong><span v-if="editablePreview" class="field-help">{{previewContext?.name}} · exercício {{previewContext?.period?.slice(0,4)||preview.period.slice(0,4)}}. {{billingOnly?'Gera somente as duplicatas XML selecionadas; nenhum dado fiscal será alterado.':isFinancial?'Importa movimentos bancários, sem conciliá-los nem registrar baixas.':reprocessing?'Atualiza somente os documentos existentes selecionados, preservando IDs e vínculos.':directPosting?'Os selecionados serão importados e escriturados no Fiscal.':'Os selecionados serão importados para conferência.'}}</span><span v-if="editablePreview&&!isFinancial" class="field-help">{{payableConsent()}}</span><span class="field-help">{{isFinancial?'Importar o extrato não confirma conciliação, pagamentos ou baixas.':'Confirmar não aprova regras fiscais nem efetua baixas financeiras.'}}</span></div><button v-if="editablePreview" class="button primary" v-allow="[routine,'import']" @click="confirm" :aria-label="billingOnly?'Gerar cobranças XML':reprocessing?'Confirmar reprocessamento':'Confirmar importação'" :disabled="busy||confirming||blocking.length>0||!selected.length||(directPosting&&!postingPreview)||reprocessDirty||financialBlocked||generatedBlocked"><Icon :name="busy?'loading':'check'"/>{{billingOnly?'Gerar cobranças XML':reprocessing?'Atualizar':'Confirmar'}} · {{selected.length}} selecionados</button><button v-else class="button outline" @click="navigate(preview.transactions?.length?'reconcile':'documents')">{{preview.transactions?.length?'Abrir conciliação':'Abrir escrituração'}}<Icon name="arrow"/></button></footer></section>
<section v-if="visualPreview" ref="visualPanel" tabindex="-1" class="panel panel-body"><h3>{{visualPreview.title}}</h3><p>Representação visual da origem, sem validação fiscal. Revise a classificação e a data de escrituração separadamente.</p><ReportPdfPreview :url="visualPreview.url" :title="visualPreview.title" @close="visualPreview=null"/></section></div></template>

